export const PersonStatusKeyToLabel = {
  'Active': 'Active',
  'Inactive': 'Inactive',
  'Suspended': 'Suspended'
} as const;
export type PersonStatusKey = keyof typeof PersonStatusKeyToLabel;

export interface Person {
  /**
   * @displayName Person ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Display Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  displayName: string;
  /**
   * @displayName Active
   * @validationRule Required for create/update operations
   */
  active: boolean;
  /**
   * @displayName Department Code
   * @validationRule Required for create/update operations
   */
  departmentCode: string;
  /**
   * @displayName Email
   * @validationRule Required for create/update operations
   */
  email: string;
  /**
   * @displayName External Object ID
   * @validationRule Required for create/update operations
   */
  externalObjectID: string;
  /**
   * @displayName Site Code
   * @validationRule Required for create/update operations
   */
  siteCode: string;
  /**
   * @displayName Status
   * @validationRule Required for create/update operations
   */
  statusKey: PersonStatusKey;
}

export const _Person = 'Person' as const;